function openFile(file) {
    let cannotOpen;
    switch (file.attachmentType) {
        case 'google-drive':
            openNewWindow(file.url);
            break;
        case 'dropbox':
            openNewWindow(file.link);
            break;
        case 'one-drive':
            openNewWindow(file['@microsoft.graph.downloadUrl']);
            break;
        default:
            cannotOpen = true;
    }
    return !cannotOpen;
}
function openNewWindow(url) {
    const win = window.open(url, '_blank');
    win?.focus();
}

