let NgcCalendarDayViewComponent = class NgcCalendarDayViewComponent extends NgcCalendarViewBaseComponent {
    /**
     * @constructor
     * @param {ChangeDetectorRef} cdRef
     * @param {TranslateService} translateService
     */
    constructor(cdRef, translateService) {
        super(cdRef, translateService, 'H');
        this.cdRef = cdRef;
        this.translateService = translateService;
        this.maxEventPerHour = 1;
    }
    /**
     * @return {void}
     */
    generatePeriod() {
        if (!this.viewDate)
            return;
        this.startDate = this.viewDate.clone().startOf('d');
        this.endDate = this.viewDate.clone().endOf('d');
        this.periodChange.emit({ startDate: this.startDate, endDate: this.endDate });
        const numberOfBlock = this.endDate.diff(this.startDate, 'h') + 1;
        this.eventBlocks = _.map(_.range(numberOfBlock), (hour) => {
            const moment = this.startDate.clone().add(hour, 'h');
            return {
                moment,
                index: moment.format(this.indexBy),
                events: [],
                showCurrentTime: this.currentTime.isSame(moment, 'h'),
                seeMore: false,
                isAdding: false,
            };
        });
    }
};
