class NgcCalendarComponent {
    constructor() {
        // @Input() public searchBox: NgcSearchBoxComponent;
        this.nameFormControl = new UntypedFormControl({ value: null, disabled: false }, [Validators.required, Validators.maxLength(255)]);
        this.selectedEventIDChange = new EventEmitter();
        this.periodChange = new EventEmitter();
        this.eventChange = new EventEmitter();
        this.eventCreate = new EventEmitter();
        this.viewDate = moment();
    }
    get classStretch() { return this.stretch; }
    /**
     * @contructor
     */
    ngOnChanges(changes) {
        if (!changes.view?.currentValue && !this.view || this.view === 'day') {
            this.selectedIndex = 0;
            this.view = 'day';
        }
        else if (this.view === 'week')
            this.selectedIndex = 1;
        else if (this.view === 'month')
            this.selectedIndex = 2;
    }
    /**
     * @param {Moment} viewDate
     * @param {number} add
     * @return {void}
     */
    changeViewDate(viewDate = moment(), add) {
        if (viewDate.isSame(this.viewDate, 'd') && !add)
            return;
        if (add)
            viewDate.add(add, this.view);
        this.viewDate = viewDate.clone();
    }
    /**
     * @param {string} view
     * @return {void}
     */
    changeView(view) {
        if (this.view === view)
            return;
        this.view = view;
        this.events = [];
        this.changeViewDate(this.viewDate);
    }
    /**
     * @param {NgcICalendarPeriod} event
     * @return {void}
     */
    changePeriod(event) {
        this.startDate = event.startDate;
        this.endDate = event.endDate;
        this.periodChange.emit(event);
    }
    /**
     * @param {NgcICalendarEvent} event
     * @param {Moment} newMoment
     * @return {void}
     */
    updateEventMoment(event, newMoment) {
        this.calendarView?.updateEventMoment(event, newMoment);
    }
}
