class NgcCollapseMenuComponent {
    constructor(_cdr) {
        this._cdr = _cdr;
        this.groupTitle = 'Platform';
        this.title = 'Playground';
        this.icon = 'code-block'; // default icon name
        this.expanded = true;
        this.activeItemLabel = '';
        this.items = [
            { label: 'History' },
            { label: 'Starred' },
            { label: 'Settings' }
        ];
        this.selectItem = new EventEmitter();
    }
    toggleExpanded() {
        this.expanded = !this.expanded;
        this._cdr.markForCheck();
    }
    selectItemAction(item) {
        this.selectItem.emit(item);
        this._cdr.markForCheck();
    }
}
