class NgcCommentBoxComponent {
    constructor(_cdr) {
        this._cdr = _cdr;
        this.subEditor = false;
        this.autoFocusOn = false;
        this.placeholder = 'Write a comment...';
        this.commentSent = new EventEmitter();
        this.cancelled = new EventEmitter();
        this.text = '';
        this.attachments = [];
        this.images = [];
        this.isFormattingVisible = false;
        this.isBold = false;
        this.isItalic = false;
    }
    get classSub() { return this.subEditor; }
    ngAfterViewInit() {
        if (this.autoFocusOn) {
            setTimeout(() => {
                this.textareaRef?.nativeElement?.focus();
            }, 100);
        }
        if (this.editingComment) {
            this.text = this.editingComment.content?.text || '';
            this.attachments = [...(this.editingComment.content?.attachments || [])];
            this.images = [...(this.editingComment.content?.images || [])];
            this._cdr.markForCheck();
        }
    }
    ngOnDestroy() {
        this.textareaRef?.nativeElement?.blur();
    }
    get isDisabled() {
        return !this.text?.trim().length && !this.attachments.length && !this.images.length;
    }
    /**
     * Send comment
     */
    sendComment() {
        if (this.isDisabled)
            return;
        const content = {
            text: this.text.trim(),
            attachments: [...this.attachments],
            images: [...this.images],
            mentions: [],
        };
        this.text = '';
        this.attachments = [];
        this.images = [];
        this.isFormattingVisible = false;
        this.commentSent.emit(content);
        this._cdr.markForCheck();
    }
    /**
     * Cancel editing
     */
    cancel() {
        this.cancelled.emit();
    }
    /**
     * Handle Enter key (send on plain Enter, allow Shift+Enter for newline)
     */
    onKeyDown(event) {
        if (event.key === 'Enter' && !event.shiftKey) {
            event.preventDefault();
            this.sendComment();
        }
        if (event.key === 'Escape') {
            event.stopPropagation();
            this.cancel();
        }
    }
    /**
     * Handle file picked from ngc-file-picker
     */
    onFilePicked(event) {
        const newFiles = event.files.map(f => ({
            name: f.name,
            size: f.size,
            url: f.url,
            previewUrl: f['@previewUrl'] || f.url,
            type: 'file',
        }));
        this.attachments.unshift(...newFiles);
        if (this.maxFilePerComment) {
            this.attachments = this.attachments.slice(0, this.maxFilePerComment);
        }
        this._cdr.markForCheck();
    }
    /**
     * Handle image picked from ngc-file-picker
     */
    onImagePicked(event) {
        const newImages = event.files.map(f => ({
            name: f.name,
            size: f.size,
            url: f.url,
            previewUrl: f['@previewUrl'] || f.url,
            type: 'image',
        }));
        this.images.unshift(...newImages);
        if (this.maxImagePerComment) {
            this.images = this.images.slice(0, this.maxImagePerComment);
        }
        this._cdr.markForCheck();
    }
    /**
     * Insert emoji into text
     */
    onEmojiPicked(emoji) {
        const el = this.textareaRef?.nativeElement;
        if (!el)
            return;
        const start = el.selectionStart || 0;
        const end = el.selectionEnd || 0;
        const native = emoji.native || '';
        this.text = this.text.slice(0, start) + native + this.text.slice(end);
        setTimeout(() => {
            el.focus();
            el.setSelectionRange(start + native.length, start + native.length);
        });
    }
    /**
     * Remove attachment
     */
    removeAttachment(index) {
        this.attachments.splice(index, 1);
        this._cdr.markForCheck();
    }
    /**
     * Remove image
     */
    removeImage(index) {
        this.images.splice(index, 1);
        this._cdr.markForCheck();
    }
}
